// OrchBiz notify-business-owner. Modes: 'dry-run' (render + log only) or 'staging' (email the staging inbox only).
// Live delivery to client staff is an operator change made only after Gate 2 approval.
const CONFIG = {
  mode: 'dry-run',
  stagingRecipient: 'staging-inbox@example.com',
  fromAddress: 'orchbiz-staging@example.com'
};
const mode = CONFIG.mode === 'staging' ? 'staging' : 'dry-run';
const state = $getWorkflowStaticData('global');
state.eventIds = state.eventIds || [];
const out = [];
for (const item of $input.all()) {
  const body = item.json.body || {};
  const problems = [];
  if (body.event !== 'lead.created') problems.push('unexpected event type: ' + body.event);
  for (const k of ['eventId', 'tenantId', 'leadId']) {
    if (!body[k]) problems.push('missing ' + k);
  }
  if (problems.length) {
    out.push({ json: { action: 'rejected', mode, problems } });
    continue;
  }
  if (state.eventIds.includes(body.eventId)) {
    out.push({ json: { action: 'duplicate-ignored', mode, eventId: body.eventId } });
    continue;
  }
  state.eventIds.push(body.eventId);
  if (state.eventIds.length > 500) state.eventIds.splice(0, state.eventIds.length - 500);
  const lead = body.lead || {};
  const fields = lead.fields || {};
  const lines = Object.entries(fields).map(([k, v]) => k + ': ' + (Array.isArray(v) ? v.join(', ') : v));
  const subject = 'New enquiry for ' + (body.tenantName || body.tenantId);
  const text = [
    'A new enquiry was received.',
    '',
    ...lines,
    '',
    'Page: ' + (lead.sourcePage || 'unknown'),
    'Received: ' + (lead.receivedAt || body.occurredAt),
    'Lead ID: ' + body.leadId,
    mode === 'staging' ? '[STAGING - test recipient only]' : ''
  ].join('\n');
  out.push({ json: {
    action: mode === 'staging' ? 'send' : 'log-only',
    mode,
    eventId: body.eventId,
    tenantId: body.tenantId,
    leadId: body.leadId,
    from: CONFIG.fromAddress,
    to: mode === 'staging' ? CONFIG.stagingRecipient : null,
    subject,
    text
  } });
}
return out;
